def test_census_excludes_llm_request_echoes():
    # The regex matches BOTH lines (the echo carries the real receipt text);
    # the census must count the COMMAND_RETURN emission only.
    assert run_benchmark.PERSIST_RECEIPT_RE.search(FALSE_LLM_REQUEST_ECHO)
    assert "LLMRequest[" not in FALSE_CMD_RETURN
    run_benchmark._docker_logs_since = (
        lambda c, s, u: FALSE_CMD_RETURN + "\n" + FALSE_LLM_REQUEST_ECHO)
    out = run_benchmark._census_persist_receipts("2026-10-28T14:54:08Z",
                                                 "2026-10-28T15:09:11Z")
    assert out["count"] == 1
    assert out["matched"] == [FALSE_CMD_RETURN]


def test_census_command_return_lane_counts():
    # A real emission line alone counts 1 (the unsolvable-case receipt).
    run_benchmark._docker_logs_since = (lambda c, s, u: UNSOLVABLE_CMD_RETURN)
    out = run_benchmark._census_persist_receipts("2026-10-28T14:33:58Z",
                                                 "2026-10-28T14:54:01Z")
    assert out["count"] == 1
    assert out["matched"] == [UNSOLVABLE_CMD_RETURN]
